// CompleteCleanup implements mm_service.PlacementService
func (mmCompleteCleanup *PlacementServiceMock) CompleteCleanup(ctx context.Context, copyID string, deleted bool, errorMessage string) (pp1 *model.PlacementCopy, err error) {
	mm_atomic.AddUint64(&mmCompleteCleanup.beforeCompleteCleanupCounter, 1)
	defer mm_atomic.AddUint64(&mmCompleteCleanup.afterCompleteCleanupCounter, 1)

	mmCompleteCleanup.t.Helper()

	if mmCompleteCleanup.inspectFuncCompleteCleanup != nil {
		mmCompleteCleanup.inspectFuncCompleteCleanup(ctx, copyID, deleted, errorMessage)
	}

	mm_params := PlacementServiceMockCompleteCleanupParams{ctx, copyID, deleted, errorMessage}

	// Record call args
	mmCompleteCleanup.CompleteCleanupMock.mutex.Lock()
	mmCompleteCleanup.CompleteCleanupMock.callArgs = append(mmCompleteCleanup.CompleteCleanupMock.callArgs, &mm_params)
	mmCompleteCleanup.CompleteCleanupMock.mutex.Unlock()

	for _, e := range mmCompleteCleanup.CompleteCleanupMock.expectations {
		if minimock.Equal(*e.params, mm_params) {
			mm_atomic.AddUint64(&e.Counter, 1)
			return e.results.pp1, e.results.err
		}
	}

	if mmCompleteCleanup.CompleteCleanupMock.defaultExpectation != nil {
		mm_atomic.AddUint64(&mmCompleteCleanup.CompleteCleanupMock.defaultExpectation.Counter, 1)
		mm_want := mmCompleteCleanup.CompleteCleanupMock.defaultExpectation.params
		mm_want_ptrs := mmCompleteCleanup.CompleteCleanupMock.defaultExpectation.paramPtrs

		mm_got := PlacementServiceMockCompleteCleanupParams{ctx, copyID, deleted, errorMessage}

		if mm_want_ptrs != nil {

			if mm_want_ptrs.ctx != nil && !minimock.Equal(*mm_want_ptrs.ctx, mm_got.ctx) {
				mmCompleteCleanup.t.Errorf("PlacementServiceMock.CompleteCleanup got unexpected parameter ctx, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmCompleteCleanup.CompleteCleanupMock.defaultExpectation.expectationOrigins.originCtx, *mm_want_ptrs.ctx, mm_got.ctx, minimock.Diff(*mm_want_ptrs.ctx, mm_got.ctx))
			}

			if mm_want_ptrs.copyID != nil && !minimock.Equal(*mm_want_ptrs.copyID, mm_got.copyID) {
				mmCompleteCleanup.t.Errorf("PlacementServiceMock.CompleteCleanup got unexpected parameter copyID, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmCompleteCleanup.CompleteCleanupMock.defaultExpectation.expectationOrigins.originCopyID, *mm_want_ptrs.copyID, mm_got.copyID, minimock.Diff(*mm_want_ptrs.copyID, mm_got.copyID))
			}

			if mm_want_ptrs.deleted != nil && !minimock.Equal(*mm_want_ptrs.deleted, mm_got.deleted) {
				mmCompleteCleanup.t.Errorf("PlacementServiceMock.CompleteCleanup got unexpected parameter deleted, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmCompleteCleanup.CompleteCleanupMock.defaultExpectation.expectationOrigins.originDeleted, *mm_want_ptrs.deleted, mm_got.deleted, minimock.Diff(*mm_want_ptrs.deleted, mm_got.deleted))
			}

			if mm_want_ptrs.errorMessage != nil && !minimock.Equal(*mm_want_ptrs.errorMessage, mm_got.errorMessage) {
				mmCompleteCleanup.t.Errorf("PlacementServiceMock.CompleteCleanup got unexpected parameter errorMessage, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmCompleteCleanup.CompleteCleanupMock.defaultExpectation.expectationOrigins.originErrorMessage, *mm_want_ptrs.errorMessage, mm_got.errorMessage, minimock.Diff(*mm_want_ptrs.errorMessage, mm_got.errorMessage))
			}

		} else if mm_want != nil && !minimock.Equal(*mm_want, mm_got) {
			mmCompleteCleanup.t.Errorf("PlacementServiceMock.CompleteCleanup got unexpected parameters, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
				mmCompleteCleanup.CompleteCleanupMock.defaultExpectation.expectationOrigins.origin, *mm_want, mm_got, minimock.Diff(*mm_want, mm_got))
		}

		mm_results := mmCompleteCleanup.CompleteCleanupMock.defaultExpectation.results
		if mm_results == nil {
			mmCompleteCleanup.t.Fatal("No results are set for the PlacementServiceMock.CompleteCleanup")
		}
		return (*mm_results).pp1, (*mm_results).err
	}
	if mmCompleteCleanup.funcCompleteCleanup != nil {
		return mmCompleteCleanup.funcCompleteCleanup(ctx, copyID, deleted, errorMessage)
	}
	mmCompleteCleanup.t.Fatalf("Unexpected call to PlacementServiceMock.CompleteCleanup. %v %v %v %v", ctx, copyID, deleted, errorMessage)
	return
}

