// MinimockCompleteCleanupDone returns true if the count of the CompleteCleanup invocations corresponds
// the number of defined expectations
func (m *PlacementServiceMock) MinimockCompleteCleanupDone() bool {
	if m.CompleteCleanupMock.optional {
		// Optional methods provide '0 or more' call count restriction.
		return true
	}

	for _, e := range m.CompleteCleanupMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			return false
		}
	}

	return m.CompleteCleanupMock.invocationsDone()
}

// MinimockCompleteCleanupInspect logs each unmet expectation
func (m *PlacementServiceMock) MinimockCompleteCleanupInspect() {
	for _, e := range m.CompleteCleanupMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to PlacementServiceMock.CompleteCleanup at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterCompleteCleanupCounter := mm_atomic.LoadUint64(&m.afterCompleteCleanupCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.CompleteCleanupMock.defaultExpectation != nil && afterCompleteCleanupCounter < 1 {
		if m.CompleteCleanupMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to PlacementServiceMock.CompleteCleanup at\n%s", m.CompleteCleanupMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to PlacementServiceMock.CompleteCleanup at\n%s with params: %#v", m.CompleteCleanupMock.defaultExpectation.expectationOrigins.origin, *m.CompleteCleanupMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcCompleteCleanup != nil && afterCompleteCleanupCounter < 1 {
		m.t.Errorf("Expected call to PlacementServiceMock.CompleteCleanup at\n%s", m.funcCompleteCleanupOrigin)
	}

	if !m.CompleteCleanupMock.invocationsDone() && afterCompleteCleanupCounter > 0 {
		m.t.Errorf("Expected %d calls to PlacementServiceMock.CompleteCleanup at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.CompleteCleanupMock.expectedInvocations), m.CompleteCleanupMock.expectedInvocationsOrigin, afterCompleteCleanupCounter)
	}
}

