				mmReserveCopy.t.Errorf("PlacementServiceMock.ReserveCopy got unexpected parameter sourceClass, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmReserveCopy.ReserveCopyMock.defaultExpectation.expectationOrigins.originSourceClass, *mm_want_ptrs.sourceClass, mm_got.sourceClass, minimock.Diff(*mm_want_ptrs.sourceClass, mm_got.sourceClass))
