// MinimockReserveCopyInspect logs each unmet expectation
func (m *PlacementServiceMock) MinimockReserveCopyInspect() {
	for _, e := range m.ReserveCopyMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to PlacementServiceMock.ReserveCopy at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterReserveCopyCounter := mm_atomic.LoadUint64(&m.afterReserveCopyCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.ReserveCopyMock.defaultExpectation != nil && afterReserveCopyCounter < 1 {
		if m.ReserveCopyMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to PlacementServiceMock.ReserveCopy at\n%s", m.ReserveCopyMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to PlacementServiceMock.ReserveCopy at\n%s with params: %#v", m.ReserveCopyMock.defaultExpectation.expectationOrigins.origin, *m.ReserveCopyMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcReserveCopy != nil && afterReserveCopyCounter < 1 {
		m.t.Errorf("Expected call to PlacementServiceMock.ReserveCopy at\n%s", m.funcReserveCopyOrigin)
	}

	if !m.ReserveCopyMock.invocationsDone() && afterReserveCopyCounter > 0 {
		m.t.Errorf("Expected %d calls to PlacementServiceMock.ReserveCopy at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.ReserveCopyMock.expectedInvocations), m.ReserveCopyMock.expectedInvocationsOrigin, afterReserveCopyCounter)
	}
}

