func (mmSwitchPlacement *mPlacementServiceMockSwitchPlacement) Inspect(f func(ctx context.Context, migrationID string, verifiedSizeBytes int64, verifiedMD5 string, sourceCleanupDelay time.Duration)) *mPlacementServiceMockSwitchPlacement {
	if mmSwitchPlacement.mock.inspectFuncSwitchPlacement != nil {
		mmSwitchPlacement.mock.t.Fatalf("Inspect function is already set for PlacementServiceMock.SwitchPlacement")
	}

	mmSwitchPlacement.mock.inspectFuncSwitchPlacement = f

	return mmSwitchPlacement
}

// Return sets up results that will be returned by PlacementService.SwitchPlacement
func (mmSwitchPlacement *mPlacementServiceMockSwitchPlacement) Return(sp1 *model.SwitchResult, err error) *PlacementServiceMock {
	if mmSwitchPlacement.mock.funcSwitchPlacement != nil {
		mmSwitchPlacement.mock.t.Fatalf("PlacementServiceMock.SwitchPlacement mock is already set by Set")
	}

	if mmSwitchPlacement.defaultExpectation == nil {
		mmSwitchPlacement.defaultExpectation = &PlacementServiceMockSwitchPlacementExpectation{mock: mmSwitchPlacement.mock}
	}
	mmSwitchPlacement.defaultExpectation.results = &PlacementServiceMockSwitchPlacementResults{sp1, err}
	mmSwitchPlacement.defaultExpectation.returnOrigin = minimock.CallerInfo(1)
	return mmSwitchPlacement.mock
}

// Set uses given function f to mock the PlacementService.SwitchPlacement method
func (mmSwitchPlacement *mPlacementServiceMockSwitchPlacement) Set(f func(ctx context.Context, migrationID string, verifiedSizeBytes int64, verifiedMD5 string, sourceCleanupDelay time.Duration) (sp1 *model.SwitchResult, err error)) *PlacementServiceMock {
	if mmSwitchPlacement.defaultExpectation != nil {
		mmSwitchPlacement.mock.t.Fatalf("Default expectation is already set for the PlacementService.SwitchPlacement method")
	}

	if len(mmSwitchPlacement.expectations) > 0 {
		mmSwitchPlacement.mock.t.Fatalf("Some expectations are already set for the PlacementService.SwitchPlacement method")
	}

	mmSwitchPlacement.mock.funcSwitchPlacement = f
	mmSwitchPlacement.mock.funcSwitchPlacementOrigin = minimock.CallerInfo(1)
	return mmSwitchPlacement.mock
}

// When sets expectation for the PlacementService.SwitchPlacement which will trigger the result defined by the following
// Then helper
func (mmSwitchPlacement *mPlacementServiceMockSwitchPlacement) When(ctx context.Context, migrationID string, verifiedSizeBytes int64, verifiedMD5 string, sourceCleanupDelay time.Duration) *PlacementServiceMockSwitchPlacementExpectation {
	if mmSwitchPlacement.mock.funcSwitchPlacement != nil {
		mmSwitchPlacement.mock.t.Fatalf("PlacementServiceMock.SwitchPlacement mock is already set by Set")
	}

	expectation := &PlacementServiceMockSwitchPlacementExpectation{
		mock:               mmSwitchPlacement.mock,
		params:             &PlacementServiceMockSwitchPlacementParams{ctx, migrationID, verifiedSizeBytes, verifiedMD5, sourceCleanupDelay},
		expectationOrigins: PlacementServiceMockSwitchPlacementExpectationOrigins{origin: minimock.CallerInfo(1)},
	}
	mmSwitchPlacement.expectations = append(mmSwitchPlacement.expectations, expectation)
	return expectation
}

// Then sets up PlacementService.SwitchPlacement return parameters for the expectation previously defined by the When method
func (e *PlacementServiceMockSwitchPlacementExpectation) Then(sp1 *model.SwitchResult, err error) *PlacementServiceMock {
	e.results = &PlacementServiceMockSwitchPlacementResults{sp1, err}
	return e.mock
}

// Times sets number of times PlacementService.SwitchPlacement should be invoked
func (mmSwitchPlacement *mPlacementServiceMockSwitchPlacement) Times(n uint64) *mPlacementServiceMockSwitchPlacement {
	if n == 0 {
		mmSwitchPlacement.mock.t.Fatalf("Times of PlacementServiceMock.SwitchPlacement mock can not be zero")
	}
	mm_atomic.StoreUint64(&mmSwitchPlacement.expectedInvocations, n)
	mmSwitchPlacement.expectedInvocationsOrigin = minimock.CallerInfo(1)
	return mmSwitchPlacement
}

func (mmSwitchPlacement *mPlacementServiceMockSwitchPlacement) invocationsDone() bool {
	if len(mmSwitchPlacement.expectations) == 0 && mmSwitchPlacement.defaultExpectation == nil && mmSwitchPlacement.mock.funcSwitchPlacement == nil {
		return true
	}

	totalInvocations := mm_atomic.LoadUint64(&mmSwitchPlacement.mock.afterSwitchPlacementCounter)
	expectedInvocations := mm_atomic.LoadUint64(&mmSwitchPlacement.expectedInvocations)

	return totalInvocations > 0 && (expectedInvocations == 0 || expectedInvocations == totalInvocations)
}

// SwitchPlacement implements mm_service.PlacementService
func (mmSwitchPlacement *PlacementServiceMock) SwitchPlacement(ctx context.Context, migrationID string, verifiedSizeBytes int64, verifiedMD5 string, sourceCleanupDelay time.Duration) (sp1 *model.SwitchResult, err error) {
	mm_atomic.AddUint64(&mmSwitchPlacement.beforeSwitchPlacementCounter, 1)
	defer mm_atomic.AddUint64(&mmSwitchPlacement.afterSwitchPlacementCounter, 1)

	mmSwitchPlacement.t.Helper()

	if mmSwitchPlacement.inspectFuncSwitchPlacement != nil {
		mmSwitchPlacement.inspectFuncSwitchPlacement(ctx, migrationID, verifiedSizeBytes, verifiedMD5, sourceCleanupDelay)
	}

	mm_params := PlacementServiceMockSwitchPlacementParams{ctx, migrationID, verifiedSizeBytes, verifiedMD5, sourceCleanupDelay}

	// Record call args
	mmSwitchPlacement.SwitchPlacementMock.mutex.Lock()
	mmSwitchPlacement.SwitchPlacementMock.callArgs = append(mmSwitchPlacement.SwitchPlacementMock.callArgs, &mm_params)
	mmSwitchPlacement.SwitchPlacementMock.mutex.Unlock()

	for _, e := range mmSwitchPlacement.SwitchPlacementMock.expectations {
		if minimock.Equal(*e.params, mm_params) {
			mm_atomic.AddUint64(&e.Counter, 1)
			return e.results.sp1, e.results.err
		}
	}

	if mmSwitchPlacement.SwitchPlacementMock.defaultExpectation != nil {
		mm_atomic.AddUint64(&mmSwitchPlacement.SwitchPlacementMock.defaultExpectation.Counter, 1)
		mm_want := mmSwitchPlacement.SwitchPlacementMock.defaultExpectation.params
		mm_want_ptrs := mmSwitchPlacement.SwitchPlacementMock.defaultExpectation.paramPtrs

		mm_got := PlacementServiceMockSwitchPlacementParams{ctx, migrationID, verifiedSizeBytes, verifiedMD5, sourceCleanupDelay}

		if mm_want_ptrs != nil {

			if mm_want_ptrs.ctx != nil && !minimock.Equal(*mm_want_ptrs.ctx, mm_got.ctx) {
				mmSwitchPlacement.t.Errorf("PlacementServiceMock.SwitchPlacement got unexpected parameter ctx, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmSwitchPlacement.SwitchPlacementMock.defaultExpectation.expectationOrigins.originCtx, *mm_want_ptrs.ctx, mm_got.ctx, minimock.Diff(*mm_want_ptrs.ctx, mm_got.ctx))
			}

			if mm_want_ptrs.migrationID != nil && !minimock.Equal(*mm_want_ptrs.migrationID, mm_got.migrationID) {
				mmSwitchPlacement.t.Errorf("PlacementServiceMock.SwitchPlacement got unexpected parameter migrationID, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmSwitchPlacement.SwitchPlacementMock.defaultExpectation.expectationOrigins.originMigrationID, *mm_want_ptrs.migrationID, mm_got.migrationID, minimock.Diff(*mm_want_ptrs.migrationID, mm_got.migrationID))
			}

			if mm_want_ptrs.verifiedSizeBytes != nil && !minimock.Equal(*mm_want_ptrs.verifiedSizeBytes, mm_got.verifiedSizeBytes) {
				mmSwitchPlacement.t.Errorf("PlacementServiceMock.SwitchPlacement got unexpected parameter verifiedSizeBytes, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmSwitchPlacement.SwitchPlacementMock.defaultExpectation.expectationOrigins.originVerifiedSizeBytes, *mm_want_ptrs.verifiedSizeBytes, mm_got.verifiedSizeBytes, minimock.Diff(*mm_want_ptrs.verifiedSizeBytes, mm_got.verifiedSizeBytes))
			}

			if mm_want_ptrs.verifiedMD5 != nil && !minimock.Equal(*mm_want_ptrs.verifiedMD5, mm_got.verifiedMD5) {
				mmSwitchPlacement.t.Errorf("PlacementServiceMock.SwitchPlacement got unexpected parameter verifiedMD5, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmSwitchPlacement.SwitchPlacementMock.defaultExpectation.expectationOrigins.originVerifiedMD5, *mm_want_ptrs.verifiedMD5, mm_got.verifiedMD5, minimock.Diff(*mm_want_ptrs.verifiedMD5, mm_got.verifiedMD5))
			}

			if mm_want_ptrs.sourceCleanupDelay != nil && !minimock.Equal(*mm_want_ptrs.sourceCleanupDelay, mm_got.sourceCleanupDelay) {
				mmSwitchPlacement.t.Errorf("PlacementServiceMock.SwitchPlacement got unexpected parameter sourceCleanupDelay, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmSwitchPlacement.SwitchPlacementMock.defaultExpectation.expectationOrigins.originSourceCleanupDelay, *mm_want_ptrs.sourceCleanupDelay, mm_got.sourceCleanupDelay, minimock.Diff(*mm_want_ptrs.sourceCleanupDelay, mm_got.sourceCleanupDelay))
			}

		} else if mm_want != nil && !minimock.Equal(*mm_want, mm_got) {
			mmSwitchPlacement.t.Errorf("PlacementServiceMock.SwitchPlacement got unexpected parameters, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
				mmSwitchPlacement.SwitchPlacementMock.defaultExpectation.expectationOrigins.origin, *mm_want, mm_got, minimock.Diff(*mm_want, mm_got))
		}

		mm_results := mmSwitchPlacement.SwitchPlacementMock.defaultExpectation.results
		if mm_results == nil {
			mmSwitchPlacement.t.Fatal("No results are set for the PlacementServiceMock.SwitchPlacement")
		}
		return (*mm_results).sp1, (*mm_results).err
	}
	if mmSwitchPlacement.funcSwitchPlacement != nil {
		return mmSwitchPlacement.funcSwitchPlacement(ctx, migrationID, verifiedSizeBytes, verifiedMD5, sourceCleanupDelay)
	}
	mmSwitchPlacement.t.Fatalf("Unexpected call to PlacementServiceMock.SwitchPlacement. %v %v %v %v %v", ctx, migrationID, verifiedSizeBytes, verifiedMD5, sourceCleanupDelay)
	return
}

// SwitchPlacementAfterCounter returns a count of finished PlacementServiceMock.SwitchPlacement invocations
func (mmSwitchPlacement *PlacementServiceMock) SwitchPlacementAfterCounter() uint64 {
	return mm_atomic.LoadUint64(&mmSwitchPlacement.afterSwitchPlacementCounter)
}

// SwitchPlacementBeforeCounter returns a count of PlacementServiceMock.SwitchPlacement invocations
func (mmSwitchPlacement *PlacementServiceMock) SwitchPlacementBeforeCounter() uint64 {
	return mm_atomic.LoadUint64(&mmSwitchPlacement.beforeSwitchPlacementCounter)
}

// Calls returns a list of arguments used in each call to PlacementServiceMock.SwitchPlacement.
// The list is in the same order as the calls were made (i.e. recent calls have a higher index)
func (mmSwitchPlacement *mPlacementServiceMockSwitchPlacement) Calls() []*PlacementServiceMockSwitchPlacementParams {
	mmSwitchPlacement.mutex.RLock()

	argCopy := make([]*PlacementServiceMockSwitchPlacementParams, len(mmSwitchPlacement.callArgs))
	copy(argCopy, mmSwitchPlacement.callArgs)

	mmSwitchPlacement.mutex.RUnlock()

	return argCopy
}

// MinimockSwitchPlacementDone returns true if the count of the SwitchPlacement invocations corresponds
// the number of defined expectations
func (m *PlacementServiceMock) MinimockSwitchPlacementDone() bool {
	if m.SwitchPlacementMock.optional {
		// Optional methods provide '0 or more' call count restriction.
		return true
	}

	for _, e := range m.SwitchPlacementMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			return false
		}
	}

	return m.SwitchPlacementMock.invocationsDone()
}

// MinimockSwitchPlacementInspect logs each unmet expectation
func (m *PlacementServiceMock) MinimockSwitchPlacementInspect() {
	for _, e := range m.SwitchPlacementMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to PlacementServiceMock.SwitchPlacement at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterSwitchPlacementCounter := mm_atomic.LoadUint64(&m.afterSwitchPlacementCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.SwitchPlacementMock.defaultExpectation != nil && afterSwitchPlacementCounter < 1 {
		if m.SwitchPlacementMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to PlacementServiceMock.SwitchPlacement at\n%s", m.SwitchPlacementMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to PlacementServiceMock.SwitchPlacement at\n%s with params: %#v", m.SwitchPlacementMock.defaultExpectation.expectationOrigins.origin, *m.SwitchPlacementMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcSwitchPlacement != nil && afterSwitchPlacementCounter < 1 {
		m.t.Errorf("Expected call to PlacementServiceMock.SwitchPlacement at\n%s", m.funcSwitchPlacementOrigin)
	}

	if !m.SwitchPlacementMock.invocationsDone() && afterSwitchPlacementCounter > 0 {
		m.t.Errorf("Expected %d calls to PlacementServiceMock.SwitchPlacement at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.SwitchPlacementMock.expectedInvocations), m.SwitchPlacementMock.expectedInvocationsOrigin, afterSwitchPlacementCounter)
	}
}

// MinimockFinish checks that all mocked methods have been called the expected number of times
func (m *PlacementServiceMock) MinimockFinish() {
	m.finishOnce.Do(func() {
		if !m.minimockDone() {
			m.MinimockAbortCopyInspect()

			m.MinimockCompleteCleanupInspect()

			m.MinimockGetPlacementInspect()

			m.MinimockListDueCleanupsInspect()

			m.MinimockListMigrationCopiesInspect()

			m.MinimockListPlacementsInspect()

			m.MinimockListStorageClassesInspect()

			m.MinimockReserveCopyInspect()

			m.MinimockSwitchPlacementInspect()
		}
	})
}

// MinimockWait waits for all mocked methods to be called the expected number of times
func (m *PlacementServiceMock) MinimockWait(timeout mm_time.Duration) {
	timeoutCh := mm_time.After(timeout)
	for {
		if m.minimockDone() {
			return
		}
		select {
		case <-timeoutCh:
			m.MinimockFinish()
			return
		case <-mm_time.After(10 * mm_time.Millisecond):
		}
	}
}

func (m *PlacementServiceMock) minimockDone() bool {
	done := true
	return done &&
		m.MinimockAbortCopyDone() &&
		m.MinimockCompleteCleanupDone() &&
		m.MinimockGetPlacementDone() &&
		m.MinimockListDueCleanupsDone() &&
		m.MinimockListMigrationCopiesDone() &&
		m.MinimockListPlacementsDone() &&
		m.MinimockListStorageClassesDone() &&
		m.MinimockReserveCopyDone() &&
		m.MinimockSwitchPlacementDone()
}
